let socket=null,myId=null,roomCode=null,lastSend=0;function connect(){const protocol=location.protocol==='https:'?'wss:':'ws:';socket=new WebSocket(`${protocol}//${location.host}`);socket.onmessage=e=>{const m=JSON.parse(e.data);if(m.type==='hello')myId=m.id;if(m.type==='joined'){roomCode=m.code;document.querySelector('#room-status').textContent=`Sala ${m.code} · ${m.players.length}/4 jugadores`;document.querySelector('#online-label').textContent=`SALA ${m.code}`;toast(`Sala ${m.code}: comparte el código con tus amigos.`)}if(m.type==='player-joined'){toast('Un jugador se ha unido a la partida.');document.querySelector('#room-status').textContent='Nuevo jugador conectado.'}if(m.type==='state'){let p=remotes.get(m.id);if(!p){p=character(m.outfit);scene.add(p);remotes.set(m.id,p)}p.userData.target=new THREE.Vector3(m.x,0,m.z);p.userData.targetRot=m.rot;if(m.outfit==='civil'&&p.children[0])p.children[0].material=M.blue}if(m.type==='player-left'){const p=remotes.get(m.id);if(p){scene.remove(p);remotes.delete(m.id)}toast('Un jugador salió de la partida.')}if(m.type==='error')document.querySelector('#room-status').textContent=m.message};socket.onclose=()=>{document.querySelector('#online-label').textContent='DESCONECTADO'}}
